package io.github.rebrowser.settings;

import static org.junit.Assert.*;
import org.junit.Test;

/** Actual production crop arithmetic, not Android ImageDecoder/Canvas qualification. */
public final class NewTabBackgroundPolicyTest {
    @Test public void portraitUsesHorizontalCenterAndTopNotVerticalCenter(){PersonalizationPolicy.Crop c=PersonalizationPolicy.centerTopCrop(3324,2493,1080,2340,4*1024*1024);assertEquals(0,c.cropY());assertTrue(c.cropX()>0);assertEquals(2493,c.cropHeight());assertEquals((3324-c.cropWidth())/2,c.cropX());assertTrue(c.outputWidth()<=1080);assertTrue(c.outputHeight()<=2340);}
    @Test public void landscapeUsesTopRatherThanEqualVerticalMargins(){PersonalizationPolicy.Crop c=PersonalizationPolicy.centerTopCrop(3324,2493,2560,1440,4*1024*1024);assertEquals(0,c.cropX());assertEquals(0,c.cropY());assertEquals(3324,c.cropWidth());assertTrue(c.cropHeight()<2493);assertTrue((long)c.outputWidth()*c.outputHeight()<=4*1024*1024);}
    @Test public void largeWindowRasterOutputRemainsBounded(){PersonalizationPolicy.Crop c=PersonalizationPolicy.centerTopCrop(3324,2493,16384,16384,4*1024*1024);assertEquals(0,c.cropY());assertTrue((long)c.outputWidth()*c.outputHeight()<=4*1024*1024);assertTrue(c.outputWidth()<=c.cropWidth());assertTrue(c.outputHeight()<=c.cropHeight());}
    @Test public void tinySourceIsNotUpscaledByDecoderGeometry(){PersonalizationPolicy.Crop c=PersonalizationPolicy.centerTopCrop(10,10,1080,2340,4*1024*1024);assertTrue(c.outputWidth()<=10);assertTrue(c.outputHeight()<=10);assertEquals(0,c.cropY());}
    @Test public void onePixelBudgetStillStaysBoundedForExtremeAspect(){PersonalizationPolicy.Crop c=PersonalizationPolicy.centerTopCrop(1,8192,1,65536,1);assertEquals(1,c.outputWidth());assertEquals(1,c.outputHeight());}
    @Test public void ownWindowHeightDoesNotChangeWithKeyboardContentShrink(){assertEquals(2256,PersonalizationPolicy.unoccludedViewportHeight(2256,2400,72,72));assertEquals(2256,PersonalizationPolicy.unoccludedViewportHeight(1200,2400,72,72));}
    @Test public void realSplitResizeAndFullscreenStillUseActualOwnWindow(){assertEquals(1256,PersonalizationPolicy.unoccludedViewportHeight(1256,1400,72,72));assertEquals(2400,PersonalizationPolicy.unoccludedViewportHeight(2400,2400,0,72));assertEquals(1056,PersonalizationPolicy.unoccludedViewportHeight(1056,1200,72,72));}
    @Test public void invalidWindowCoordinatesAreNotAcceptedAsGeometry(){assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.unoccludedViewportHeight(0,2400,72,72));assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.unoccludedViewportHeight(1200,2400,-1,72));assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.unoccludedViewportHeight(1200,65537,72,72));}
    @Test public void invalidOrUnboundedGeometryRejects(){assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.centerTopCrop(0,2493,1080,2340,1));assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.centerTopCrop(9000,9000,1080,2340,1));assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.centerTopCrop(3324,2493,0,2340,1));assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.centerTopCrop(3324,2493,1080,65537,1));assertThrows(IllegalArgumentException.class,()->PersonalizationPolicy.centerTopCrop(3324,2493,1080,2340,0));}
    @Test public void approvedAspectSamplesStayWithinSourceAndDecodedPixelLimit(){int[][] sizes={{360,780},{1080,2340},{2560,1600},{1280,720},{720,1280},{280,800},{3000,300},{800,280},{100,65536},{65536,100}};for(int[] size:sizes){PersonalizationPolicy.Crop c=PersonalizationPolicy.centerTopCrop(3324,2493,size[0],size[1],4*1024*1024);assertEquals(0,c.cropY());assertTrue(c.cropX()>=0);assertTrue(c.cropX()+c.cropWidth()<=3324);assertTrue(c.cropHeight()<=2493);assertTrue((long)c.outputWidth()*c.outputHeight()<=4*1024*1024);assertTrue(c.outputWidth()>0 && c.outputHeight()>0);}}
}
